/**
 * WRITE `src/lib/pools/registry.ts` FROM `db/*.sql`.
 *
 *     npm run gen:pools            # rewrite the file
 *     npm run check:pools          # fail if it is stale
 *
 * The registry is a DATABASE table (`ingredient_pool`, `facet_tag_entity`) and
 * several of its consumers are TYPESCRIPT UNIONS. A union cannot be read out of
 * Postgres at compile time, so the honest move is to generate the union from
 * the only description of the schema that ships in the repo — the migrations —
 * and then have a test check the generated file against BOTH the migrations
 * (always) and a live database (when one is configured). See the essay at the
 * top of src/lib/pools/derive.ts for why the migrations and not the database
 * are the compile-time source, and src/lib/pools/registry.test.ts for what is
 * asserted.
 *
 * This script never has to be remembered: `registry.test.ts` fails if the file
 * on disk disagrees with `db/`, and the failure message says to run this.
 */
import { writeFileSync, readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

import { deriveEntities, deriveRequirable } from "../src/lib/pools/derive.ts";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const target = join(root, "src", "lib", "pools", "registry.ts");

const entities = deriveEntities(join(root, "db"));
const requirable = deriveRequirable(join(root, "db"));

if (entities.length === 0) {
  throw new Error("no pools derived from db/ — refusing to write an empty registry");
}
if (!requirable) {
  throw new Error("no ingredient_requirement_known_pool CHECK found in db/");
}

const q = (value) => (value === null ? "null" : JSON.stringify(value));

/** The pools that can actually be issued: an ingredient_pool row WITH a join. */
const stocked = entities.filter((e) => e.ingredient && e.joinTable);
const facetted = entities.filter((e) => e.facetTable);

const body = `/**
 * GENERATED BY scripts/generate-pool-registry.mjs — DO NOT EDIT BY HAND.
 *
 *     npm run gen:pools
 *
 * WHAT POOLS EXIST. Nothing else. This file is the single answer to a question
 * that used to be answered independently in six places, and got a different
 * answer in four of them (CLAUDE.md rule 19).
 *
 * ── THE BOUNDARY THIS FILE DRAWS ─────────────────────────────────────
 *
 * DERIVED AT RUNTIME, and not here: everything \`ingredient_pool\` holds that a
 * migration can UPDATE after the fact — \`typical_draw\`, \`label\`,
 * \`label_column\`, \`active_column\`. db/022 moves dish to 3 and menu to 0
 * without touching any installer call, so a copy here would be a second opinion
 * kept current by hand. src/lib/desk/publish.ts and src/lib/desk/connections.ts
 * read those live and are right to.
 *
 * GENERATED AND VERIFIED, which is this file: WHICH pools exist and what their
 * four scoping tables are called. These are needed as TYPES — \`Record<StockedPool,
 * Spec>\` in the engine's catalogue, \`Taggable\` in the desk — and a type is gone
 * before a connection is ever opened, so a runtime read cannot produce the
 * compile error rule 19 asks for. Generating the constant and CHECKING IT
 * AGAINST THE DATABASE IN A TEST is the closest honest thing: the compiler
 * catches the consumer that forgot a pool, and the test catches this file
 * drifting from the schema. Neither alone is enough, which is why it is both.
 *
 * IRREDUCIBLY HAND-AUTHORED, and deliberately absent: which COLUMN holds the
 * sentence a member reads (src/lib/portal/picks.ts's \`RENDERING\`, and the
 * \`describe\`/\`mirror\` fields of the engine's catalogue), and which desk screen
 * shows a pool (src/lib/desk/stocked.ts's \`POOL_SCREEN\`). A menu's line of
 * dishes IS the thing and a drink carries two authored builds on one row; those
 * are facts about AUTHORING and about ROUTES, the registry has no column for
 * them and should not grow one. What this file gives them is a KEY SET they
 * must cover, so forgetting one is a compile error even though the value
 * itself can only be written by a person.
 */

/** One entity the migrations registered, with the tables they installed. */
export type PoolEntity = {
  /** \`ingredient_pool.entity_table\` / \`facet_tag_entity.entity_table\`. */
  readonly pool: string;
  /** It has a row of \`ingredient_pool\`. False for \`taste_cohort\` alone. */
  readonly ingredient: boolean;
  /** \`ingredient_pool.join_table\`. Null for \`world\` — see below. */
  readonly joinTable: string | null;
  /** \`facet_tag_entity.join_table\`, always \`<pool>_facet\`. */
  readonly facetTable: string | null;
  /** \`ingredient_pool.occasion_table\`. */
  readonly occasionTable: string | null;
  /** \`ingredient_pool.slot_table\`. */
  readonly slotTable: string | null;
  /** \`ingredient_pool.world_table\`. */
  readonly worldTable: string | null;
};

/** Every registered entity, both registries, sorted by name. */
export const POOL_ENTITIES = [
${entities
  .map(
    (e) => `  {
    pool: ${q(e.pool)},
    ingredient: ${e.ingredient},
    joinTable: ${q(e.joinTable)},
    facetTable: ${q(e.facetTable)},
    occasionTable: ${q(e.occasionTable)},
    slotTable: ${q(e.slotTable)},
    worldTable: ${q(e.worldTable)},
  },`
  )
  .join("\n")}
] as const satisfies readonly PoolEntity[];

/**
 * Anything either registry knows about — including \`taste_cohort\`, which is
 * tagged but never issued.
 */
export type EntityTable = (typeof POOL_ENTITIES)[number]["pool"];

/**
 * A POOL THE ENGINE CAN DRAW FROM: a row of \`ingredient_pool\` with a
 * \`join_table\`.
 *
 * \`world\` is excluded and that is not an oversight. It has an
 * \`ingredient_pool\` row with a NULL join table because db/001 already carries
 * the chosen destination as \`revelle.world_id\`; a destination is the frame the
 * evening is drawn in, not a thing drawn into it. Anything looping to SELECT
 * ingredients wants this union. Anything looping to RENDER a desk screen wants
 * \`ENTITY_TABLES\`, because destinations have one.
 */
export type StockedPool = Extract<
  (typeof POOL_ENTITIES)[number],
  { ingredient: true; joinTable: string }
>["pool"];

/** An entity with a \`<pool>_facet\` table, i.e. a row of \`facet_tag_entity\`. */
export type FacetEntity = Extract<
  (typeof POOL_ENTITIES)[number],
  { facetTable: string }
>["pool"];

/** Every entity name, sorted. */
export const ENTITY_TABLES = [
${entities.map((e) => `  ${q(e.pool)},`).join("\n")}
] as const satisfies readonly EntityTable[];

/** The pools the engine can draw from, sorted. Excludes \`world\`. */
export const STOCKED_POOLS = [
${stocked.map((e) => `  ${q(e.pool)},`).join("\n")}
] as const satisfies readonly StockedPool[];

/** The entities that can carry facet tags, sorted. */
export const FACET_ENTITIES = [
${facetted.map((e) => `  ${q(e.pool)},`).join("\n")}
] as const satisfies readonly FacetEntity[];

/**
 * The pools db/033's CHECK on \`ingredient_requirement.entity_table\` accepts.
 *
 * Read out of the migration rather than assumed equal to \`STOCKED_POOLS\`,
 * because this constraint HAS DRIFTED: db/020 wrote five pools into it, three
 * more were registered, and db/033 had to repair it. If it ever falls behind
 * again the two lists differ here, in a generated file, and registry.test.ts
 * says so — instead of a curator getting a 500 from a constraint violation.
 */
export const REQUIRABLE_POOLS = [
${requirable.map((p) => `  ${q(p)},`).join("\n")}
] as const;

export type RequirablePool = (typeof REQUIRABLE_POOLS)[number];

/** Index by pool, for the lookups below. */
const BY_POOL: Readonly<Record<string, PoolEntity>> = Object.fromEntries(
  POOL_ENTITIES.map((entity) => [entity.pool, entity])
);

/**
 * The four scoping tables of one pool, BY LOOKUP RATHER THAN CONCATENATION.
 *
 * The difference matters and is the whole of rule 19's second clause.
 * \`\${table}_world\` at the point of use is a guess that is right until a pool
 * is registered without that installer having run — which is exactly what
 * db/031 did, leaving \`bank_item\` with a \`revelle_bank_item\` and no
 * \`bank_item_world\` until db/043 filled it in. A guess returns a name for a
 * table that does not exist and fails as a 500 at the far end of a query. This
 * returns \`null\`, in the type, where the caller has to decide what that means.
 */
export function tablesFor(pool: string): PoolEntity | null {
  return BY_POOL[pool] ?? null;
}

/** \`<pool>_facet\`, from the registry. Never composed at the point of use. */
export function facetTableFor(pool: FacetEntity): string {
  const table = BY_POOL[pool]?.facetTable;
  if (!table) throw new Error(\`no facet table registered for pool '\${pool}'\`);
  return table;
}

/**
 * The column a join table points back at the entity with — \`<pool>_id\`.
 *
 * Both installers compute it the same way (\`v_column := p_entity_table ||
 * '_id'\` in db/002 and db/009) and no migration overrides it, so unlike the
 * table names there is nothing per-pool to store. It is derived here, once,
 * next to the migration text it was read from.
 */
export function idColumnFor(pool: EntityTable): string {
  return \`\${pool}_id\`;
}
`;

const previous = (() => {
  try {
    return readFileSync(target, "utf8");
  } catch {
    return null;
  }
})();

if (previous === body) {
  console.log(`src/lib/pools/registry.ts is current (${entities.length} entities)`);
} else if (process.argv.includes("--check")) {
  console.error(
    "src/lib/pools/registry.ts is STALE — a migration registered or renamed a pool.\n" +
      "Run: npm run gen:pools"
  );
  process.exit(1);
} else {
  writeFileSync(target, body);
  console.log(
    `wrote src/lib/pools/registry.ts — ${entities.length} entities, ` +
      `${stocked.length} stocked, ${facetted.length} taggable`
  );
}
